sql.sql:
select job.* from 
(select r.job_code,r.status,r.workflow_id,r.create_time,r.complete_time,r.workflow_name,r.begin_cell_code from t_job_record r
union
select rh.job_code,rh.status,rh.workflow_id,rh.create_time,rh.complete_time,rh.workflow_name,rh.begin_cell_code from t_job_record_history rh
) as job
order by job.create_time desc limit #{limit}

 select count(job.id) as count_all, sum(case when job.status in (30,35) then 1 else 0 end) as count_finish, sum(case when job.status=10 then 1 else 0 end) as count_wait, sum(case when job.status in(20,50) then 1 else 0 end) as count_executing, sum(case when job.status in(28,31) then 1 else 0 end) as count_cancel, sum(case when job.status=60 then 1 else 0 end) as count_start_error, sum(case when job.status=100 then 1 else 0 end) as count_else_statusfrom 
(select r.id,r.workflow_id ,r.status,r.warn_info,r.create_time from t_job_record r where r.complete_time >= #{begin} or r.complete_time is null
union
select rh.id,rh.workflow_id ,rh.status,rh.warn_info,rh.create_time from t_job_record_history rh where rh.complete_time >= #{begin}
) as job
